/**
 * The month-end run. T-140, and the live half of **DEF-044**.
 *
 * ## ⭐ Why this file exists at all
 *
 * Both runners were already idempotent and safe to re-run. **Nothing called either of them without
 * a human pressing a button** — which is v1's exact shape: its seed data claims depreciation is
 * *"auto-generated by the depreciation cron"* and no such cron has ever existed. It stopped for two
 * months, ₱35,483.98 a month went unbooked, and it was found by an **audit** rather than by anybody
 * noticing.
 *
 * ## ⭐ The run RECORDS ITSELF, and that is the point
 *
 * Everywhere else here a figure is derived and never stored. This is the deliberate exception:
 *
 * - a month that **posted** is derivable — the entry is right there
 * - a month that **failed** is ⛔ **not** — a failure leaves no trace by construction
 * - a run that **never happened** is ⛔ **not**, and that is DEF-044 exactly
 *
 * So every run writes a `scheduler_runs` row **even when it posts nothing**, because *"it ran and
 * there was nothing to do"* and *"it never ran"* must be tellable apart. A scheduler that fails
 * quietly is **worse than the button**, since nobody is even expecting to press anything.
 */
import {
  filesRepo,
  fiscalPeriodsRepo,
  schedulerRepo,
  storesRepo,
  systemTransaction,
  withOrgPrincipal,
  withSystemOrgPrincipal,
  type SchedulerFailure,
  type SchedulerJob,
  type Tx,
} from '@shareat/db';
import { runDepreciationAsSystem } from '../fixed-assets/depreciate';
import { runAmortisationAsSystem } from '../prepaid';
import { runOrderWastageBackstop } from '../wastage/orders';
import { sweepOrphanedFiles } from '../files';
import { fiscalPeriodSeedWindow } from '../organizations';
import { autoPostDueUsageDrafts } from '../stock/usage-auto-post';
import { classifyHoles } from '../fiscal-periods';

import { money, toBusinessDate } from '@shareat/core';
import { sql } from 'drizzle-orm';
import { sweepStore } from '../attendance/sweep';
import { drainOutbox, ingestEvents, type InboxDriver, type MirrorDriver } from '../sync';
import { recordFindingObservations } from '../findings';
import { budgetsRepo, expensesRepo } from '@shareat/db';
import { nextPeriodKey, resetWindowDays } from '../budgets';

export interface MonthEndOptions {
  /** `YYYY-MM` to run THROUGH. Defaults to the last completed month. */
  period?: string;
  /** ⭐ Distinguishes "nobody has run it since March" from "the cron died in March and someone
   *  has been clicking the button". */
  trigger?: 'cron' | 'manual';
  /** Limits the run to one org. Omitted runs every org. */
  orgId?: string;
}

export interface JobOutcome {
  orgId: string;
  orgName: string;
  // T-344 — was an inline union hand-copied from SCHEDULER_JOBS; now the derived type itself, so
  // the two can never silently drift apart (packages/db/schema/scheduler.ts:105).
  job: SchedulerJob;
  period: string;
  posted: number;
  skipped: number;
  failed: number;
  failures: SchedulerFailure[];
  error?: string;
  /**
   * T-204 — `inbox_relay` only. A punch that landed safely but whose day's recompute failed (most
   * commonly: the day is already frozen by a paid pay run). ⛔ Deliberately NOT folded into
   * `failed`/`failures` — the punch itself succeeded, only its adjudication didn't — but it must
   * still be visible somewhere on the outcome rather than silently dropped (bible §15.6).
   */
  adjudicationFailures?: { clientPunchId: string; detail: string }[];
  /**
   * T-214 — `finding_observation` only. Which months the run asked about, and how many occurrences
   * it observed, opened and closed. ⚠️ The periods list is the part worth printing: it is the
   * evidence that a month with an open occurrence was actually RE-ASKED rather than quietly
   * abandoned at the boundary, which is the difference between a clear rate and a lie.
   */
  detail?: string;
}

export interface MonthEndResult {
  period: string;
  outcomes: JobOutcome[];
  /** True when anything at all went wrong — the CLI turns this into a non-zero exit code so the
   *  host's cron mailer notices. */
  hadFailures: boolean;
}

/** What a job's body reports back. The helper turns this into a `JobOutcome` and a run row. */
interface JobWork {
  posted: number;
  skipped: number;
  failures: SchedulerFailure[];
  detail?: string;
  adjudicationFailures?: { clientPunchId: string; detail: string }[];
}

/**
 * ⭐ T-233 — DEF-219: the seam every one of the ten `startRun` placements now calls, instead of
 * copying `startRun`/`try`/`finishRun`/`catch`/`failRun` identically nine (now ten) times.
 *
 * **It never throws.** Every path returns a `JobOutcome`. That single property is what makes "no
 * org after the first is skipped" true — the loops above depend on it, not on this function being
 * careful in any one caller.
 */
export async function runJobForOrg(
  org: { id: string; name: string },
  job: SchedulerJob,
  period: string,
  trigger: 'cron' | 'manual',
  work: () => Promise<JobWork>,
  startedAt?: Date,
): Promise<JobOutcome> {
  const base = { orgId: org.id, orgName: org.name, job, period };

  // Guard A — `startRun` refused. No run row exists and none can be written, so the failure lives
  // only on the in-memory outcome. The prefix is load-bearing: "the run failed" and "the run was
  // never opened" are different facts with different fixes, and there is no row to carry a flag.
  let runId: string;
  try {
    runId = await systemTransaction((tx) => schedulerRepo.startRun(tx, { orgId: org.id, job, period, trigger, ...(startedAt ? { startedAt } : {}) }));
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return {
      ...base,
      posted: 0,
      skipped: 0,
      failed: 0,
      failures: [],
      error: `could not open a scheduler run row — ${message}`,
    };
  }

  // Guard B — `work()` threw. The row exists; best-effort `failRun`, its own failure swallowed and
  // appended rather than left to escape and reject this org's outcome.
  let result: JobWork;
  try {
    result = await work();
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const note = await closeFailedRun(runId, message);
    return { ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message + note };
  }

  // Guard C — `finishRun` threw, after the work committed. The outcome keeps the REAL counts and
  // adds the error: reporting `posted: 0` here would be the exact lie `runDepreciationJob`'s own
  // comment rails against, wearing its other face. The row is left unfinished for `unfinishedRuns`.
  try {
    await systemTransaction((tx) =>
      schedulerRepo.finishRun(tx, runId, {
        postedCount: result.posted,
        skippedCount: result.skipped,
        failures: result.failures,
      }),
    );
    return { ...base, ...result, failed: countFailures(result.failures) };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return {
      ...base,
      ...result,
      failed: countFailures(result.failures),
      error: `could not close the scheduler run row — ${message}`,
    };
  }
}

/** Failures only: a `kind: 'notice'` entry is said, not failed (T-368), so it is never counted. */
function countFailures(failures: SchedulerFailure[]): number {
  return failures.filter((f) => f.kind !== 'notice').length;
}

/** Best-effort `failRun`; if it also fails, the row stays `finished_at IS NULL` — which
 *  `unfinishedRuns` already reports as "started and never reported back", so the swallow loses
 *  nothing. */
async function closeFailedRun(runId: string, message: string): Promise<string> {
  try {
    await systemTransaction((tx) => schedulerRepo.failRun(tx, runId, message));
    return '';
  } catch (err) {
    const note = err instanceof Error ? err.message : String(err);
    return ` (and the run row could not be closed: ${note})`;
  }
}

/**
 * The last COMPLETED month, as `YYYY-MM`.
 *
 * ⚠️ Not the current month. Running on the 1st is the normal case, and depreciating a month that
 * has not finished would post a charge for days that have not happened.
 *
 * ⛔ DEF-283: derived from `toBusinessDate` (Asia/Manila), not raw UTC getters. A job firing at
 * 03:00 Manila on the 1st is still the last hour of the previous day in UTC, so the raw-UTC idiom
 * closed the month before the one that had just ended — silently, since the close is idempotent.
 * `packages/core/src/datetime.ts` is the one sanctioned date module; do not add a second idiom here.
 */
export function lastCompletedPeriod(today = new Date()): string {
  const [yStr, mStr] = toBusinessDate(today).split('-');
  const y = Number(yStr);
  const m = Number(mStr); // 1-based business month in Asia/Manila
  const year = m === 1 ? y - 1 : y;
  const month = m === 1 ? 12 : m - 1;
  return `${year}-${String(month).padStart(2, '0')}`;
}

/**
 * The scheduler's one way to enumerate organisations to run a job for. Centralised so
 * `systemTransaction` has exactly one call site to reach through here, not seven independently
 * editable ones — DEF-211's "centralise the idiom" instinct, applied to keep Contract 1's closed
 * caller list actually closed rather than aspirational.
 */
export async function listOrgsToRun(orgId?: string) {
  return systemTransaction((tx) => schedulerRepo.listOrgsToRun(tx, orgId));
}

/**
 * Runs both jobs for every org, recording each one.
 *
 * ⚠️ **One org failing must never stop the next**, and neither may one asset stop another — the
 * per-item transactions live in the runners themselves (T-124 §12, T-125). Here the guard is only
 * that an org whose job throws outright still gets a row saying so.
 */
export async function runMonthEnd(options: MonthEndOptions = {}): Promise<MonthEndResult> {
  const period = options.period ?? lastCompletedPeriod();
  const trigger = options.trigger ?? 'cron';

  const orgs = await listOrgsToRun(options.orgId);
  const outcomes: JobOutcome[] = [];

  for (const org of orgs) {
    outcomes.push(await runDepreciationJob(org, period, trigger));
    outcomes.push(await runAmortisationJob(org, period, trigger));
  }

  return {
    period,
    outcomes,
    hadFailures: outcomes.some((o) => o.failed > 0 || o.error),
  };
}

async function runDepreciationJob(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
): Promise<JobOutcome> {
  return runJobForOrg(org, 'depreciation', period, trigger, async () => {
    // `through` is the last day of the period — the runner takes a date, not a period.
    const result = await runDepreciationAsSystem(org.id, { through: endOfPeriod(period) });
    const failures: SchedulerFailure[] = result.failed.map((f) => ({
      subjectId: f.assetId,
      subjectName: f.assetName,
      reason: f.error,
    }));

    // ⚠️ COUNT ONLY WHAT WAS ACTUALLY CREATED. `runDepreciation.posted` includes periods that
    // were already posted and no-opped (`created: false`) — it is a list of postings CONSIDERED,
    // not written. Reporting its length made the second run of a month claim "posted 2" while
    // writing nothing.
    //
    // ⛔ That is DEF-044 wearing the other mask: a scheduler that reports work it did not do looks
    // healthy forever, and the number nobody can trust is worse than no number. Caught by running
    // it twice and counting the ledger, which is the only way it shows.
    const created = result.posted.filter((p) => p.created).length;
    const alreadyThere = result.posted.length - created;
    // T-368: owed months skipped because their fiscal period is closed are NOT "not due" and NOT failures -
    // said once, as a notice, so a cron run is never silent about them (T-345's list is where they are booked).
    if (result.skippedClosed > 0) {
      failures.push({
        subjectId: org.id,
        subjectName: 'Depreciation',
        reason: `${result.skippedClosed} month(s) owed in a closed month — book them from Findings (missed months).`,
        kind: 'notice',
      });
    }
    return { posted: created, skipped: result.skipped + alreadyThere, failures };
  });
}

async function runAmortisationJob(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
): Promise<JobOutcome> {
  return runJobForOrg(org, 'amortisation', period, trigger, async () => {
    const result = await runAmortisationAsSystem(org.id, period);
    const failures: SchedulerFailure[] = result.failed.map((f) => ({
      subjectId: f.itemId,
      subjectName: f.itemName,
      reason: f.error,
    }));
    return { posted: result.posted.length, skipped: result.skipped, failures };
  });
}

/** Last day of a `YYYY-MM`, as `YYYY-MM-DD`. Day 0 of the next month, so February needs no table. */
function endOfPeriod(period: string): string {
  const [y, m] = period.split('-').map(Number) as [number, number];
  const d = new Date(Date.UTC(y, m, 0));
  return d.toISOString().slice(0, 10);
}

// =====================================================================================

/**
 * ⭐ **T-199 — the attendance sweep, on the same scheduler as month-end.**
 *
 * ⚠️ **Hourly, not daily**, and that is what drives everything below: the cut-off is a wall-clock
 * hour **per store** (v1: all three on 02:00). A daily timer could not serve two stores on
 * different hours, so the timer fires every hour and each store decides whether its hour has come
 * round. A store whose hour has not arrived is a no-op, cheaply.
 */
export interface SweepResult {
  outcomes: JobOutcome[];
  hadFailures: boolean;
}

export async function runAttendanceSweep(
  options: { orgId?: string; trigger?: 'cron' | 'manual'; nowMs?: number } = {},
): Promise<SweepResult> {
  const trigger = options.trigger ?? 'cron';
  const nowMs = options.nowMs ?? Date.now();
  // ⚠️ `scheduler_runs.period` is shaped `YYYY-MM` by a CHECK. An hourly job has no month of its
  // own, so it records the month it RAN in; `started_at` is what distinguishes one run from the
  // next, and there is deliberately no unique key on (org, job, period).
  const period = new Date(nowMs + 8 * 3_600_000).toISOString().slice(0, 7);

  const orgs = await listOrgsToRun(options.orgId);
  const outcomes: JobOutcome[] = [];

  for (const org of orgs) {
    outcomes.push(await runSweepForOrg(org, period, trigger, nowMs));
  }
  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}

async function runSweepForOrg(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  nowMs: number,
): Promise<JobOutcome> {
  return runJobForOrg(org, 'attendance_sweep', period, trigger, async () => {
    // DEF-287: `asSystem`, not a bare `transaction`. `stores` is org-scoped under FORCE RLS, so
    // with no principal this returns zero rows and the sweep reports a clean run over nothing.
    // T-343 S4 — `s.name`/`s.code` added to this SAME select (no extra query) so a per-store
    // failure below can name the store, never its id.
    const stores = await asSystem(org.id, (tx) =>
      tx.execute(
        sql`select s.id::text as "id", s.name as "name", s.code as "code" from stores s
             join store_attendance_config c on c.store_id = s.id and c.superseded_at is null
            where s.org_id = ${org.id}`,
      ),
    );

    let swept = 0;
    let leftOpen = 0;
    const failures: SchedulerFailure[] = [];

    // ⛔ One transaction PER STORE, matching T-124 §12's reasoning that month-end already follows:
    // one bad store must not roll back the ones that succeeded. The day is derived, so a partial
    // sweep is incomplete, never inconsistent.
    for (const store of stores as unknown as { id: string; name: string; code: string }[]) {
      try {
        const out = await asSystem(org.id, (tx) => sweepStore(tx, { storeId: store.id, nowMs }));
        swept += out.swept.length;
        leftOpen += out.leftOpen;
      } catch (err) {
        failures.push({
          subjectId: store.id,
          subjectName: `${store.name} (${store.code})`,
          reason: err instanceof Error ? err.message : String(err),
        });
      }
    }

    return { posted: swept, skipped: leftOpen, failures };
  });
}

