/**
 * ⭐ **T-276 / DEF-305 — the monthly fiscal-period coverage top-up, MONTHLY, 1st.**
 *
 * `bootstrapOrganization` seeds 12 months of fiscal periods once, at creation (T-264/DEF-284), and
 * nothing has topped that up since — an org running past its first year eventually reaches a month
 * `postEntry` has no period for at all, and every post that month is refused (the DEF-305 gap).
 * This job keeps every org's coverage 12 months ahead of its current Manila business month and, per
 * the approved design **option (c)**, backfills any month that already ELAPSED with no period at
 * all — created `open`, never closed retroactively (invariant 1) — so the gap is surfaced as a
 * `scheduler_runs` failure line instead of silently blocking the next post someone tries.
 *
 * ## §1's rule, in code: the gap threshold
 *
 * Let `M` = the current business month (Asia/Manila, via `fiscalPeriodSeedWindow`'s own
 * `toBusinessDate` conversion — DEF-283, never a raw-UTC shift) and `F` = the org's latest period
 * end (any status), read inside the SAME transaction the seed writes into.
 *
 * | Case | Seed window | Failure line |
 * |---|---|---|
 * | `F` is `null` (no periods at all — abnormal; an org this bare is worth a line even though the seed itself is ordinary) | `M`, 12 months | *"no fiscal periods existed at all…"* |
 * | the month after `F` is `M` or earlier (ordinary running coverage, including a legacy period that already reaches past `M`) | `M`, 12 months | none — `ok` |
 * | the month after `F` is BEFORE `M` (one or more whole months elapsed with no period) | from the month after `F`, `gapMonths + 12` months | *"coverage gap…"*, gated on `periodsInserted >= gapMonths` so an overlapping run never re-reports a gap the winner already closed |
 *
 * `monthIndex`/`addMonths` below are this rule's own month arithmetic, module-private on purpose —
 * nothing else in this codebase needs "which month is N months after this one" as a public API,
 * and a zero-caller export is exactly the DEF-186 shape T-236's own guard exists to catch.
 */
export async function runFiscalPeriodSeed(
  options: { orgId?: string; trigger?: 'cron' | 'manual'; nowMs?: number } = {},
): Promise<SweepResult> {
  const trigger = options.trigger ?? 'cron';
  const nowMs = options.nowMs ?? Date.now();
  // Same bookkeeping-only convention as every job above except month-end: the run row records the
  // Manila month this run happened IN, not a period being closed — this job has no "through" period
  // of its own, it tops up whatever window §1 computes.
  const period = new Date(nowMs + 8 * 3_600_000).toISOString().slice(0, 7);

  const orgs = await listOrgsToRun(options.orgId);
  const outcomes: JobOutcome[] = [];
  for (const org of orgs) {
    outcomes.push(await runFiscalPeriodSeedForOrg(org, period, trigger, nowMs));
  }
  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}

/** `YYYY-MM` → a linear month index, so "N months after/before" is one subtraction. */
function monthIndex(yyyyMm: string): number {
  const [y, m] = yyyyMm.split('-').map(Number) as [number, number];
  return y * 12 + (m - 1);
}

/** `YYYY-MM` shifted by `delta` months (either direction), back to `YYYY-MM`. */
function addMonths(yyyyMm: string, delta: number): string {
  const idx = monthIndex(yyyyMm) + delta;
  const y = Math.floor(idx / 12);
  const m = (idx % 12) + 1;
  return `${y}-${String(m).padStart(2, '0')}`;
}

async function runFiscalPeriodSeedForOrg(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  nowMs: number,
): Promise<JobOutcome> {
  return runJobForOrg(org, 'fiscal_period_seed', period, trigger, async () => {
    // `fiscalPeriodSeedWindow` is the SAME function `bootstrapOrganization` uses (T-264 — one
    // definition of "12 months forward, from the org's own Manila business month"); only its
    // `startYear`/`startMonth` are used here — `months` is recomputed below when there is a gap.
    const m = fiscalPeriodSeedWindow(new Date(nowMs));
    const mLabel = `${m.startYear}-${String(m.startMonth).padStart(2, '0')}`;

    // DEF-287/§15.11 — system principal, ONE transaction for this org's whole read-plan-seed
    // (never a bare `systemTransaction`). ⚠️ **Corrected (T-344): this transaction does NOT by
    // itself close the TOCTOU between the read below and the writes that follow** — under READ
    // COMMITTED each statement gets its own fresh snapshot, so a concurrent `closePeriod` can still
    // commit in between. What actually closes it: every A-fill insert is idempotent (`ON CONFLICT
    // DO NOTHING`, `seedCalendarMonths`), so a race just means fewer rows for the loser to insert;
    // and migration 0160's `fiscal_periods_order_guard` trigger takes a per-org advisory lock on
    // every insert/status change and RE-CHECKS the open/closed ordering after acquiring it, which
    // is what actually serialises this job's write against a concurrent close (R1.2, H13).
    return asSystem(org.id, async (tx) => {
      const before = await fiscalPeriodsRepo.latestPeriodEnd(tx, org.id);

      // Zero-period branch — unchanged (T-344 §3.2).
      if (before === null) {
        const { periodsInserted, periodsSkipped } = await fiscalPeriodsRepo.seedCalendarMonths(tx, org.id, {
          startYear: m.startYear,
          startMonth: m.startMonth,
          months: 12,
        });
        const after = await fiscalPeriodsRepo.latestPeriodEnd(tx, org.id);
        const failures: SchedulerFailure[] = [];
        if (periodsInserted > 0) {
          failures.push({
            subjectId: org.id,
            subjectName: org.name,
            reason:
              `no fiscal periods existed at all; seeded ${mLabel}..${addMonths(mLabel, 11)} forward only ` +
              '— no earlier month was invented',
          });
        }
        return {
          posted: periodsInserted,
          skipped: periodsSkipped,
          failures,
          detail:
            `window ${mLabel}..${addMonths(mLabel, 11)} · inserted ${periodsInserted} · ` +
            `skipped ${periodsSkipped} · coverage now ends ${after ?? 'never'}`,
        };
      }

      // T-344 §3.2 — classify every hole through M+11 BEFORE any write below. This is a plain
      // SELECT, which the order-guard trigger's advisory lock never blocks, so it reflects
      // coverage as of the moment this run actually started — even while a concurrent close is
      // mid-transaction and holding that lock (H13). The writes that follow are what the lock (and
      // its re-check after acquiring it) protects.
      const through = monthEndFromLabel(addMonths(mLabel, 11));
      const { pieces } = await classifyHoles(tx, org.id, through);

      interface ARun {
        startsOn: string;
        endsOn: string;
        pieces: typeof pieces;
      }
      // Class A — group into contiguous whole-month runs (never crosses a hole boundary: a real
      // period always separates two holes, so two different holes' pieces can never be date-
      // adjacent). Grouped over the FULL run, unclipped — §3.2's Tail/Interior distinction below
      // needs the run's true extent, not just its elapsed prefix.
      const aRuns: ARun[] = [];
      let current: ARun | null = null;
      for (const piece of pieces) {
        if (piece.class !== 'A') {
          current = null;
          continue;
        }
        if (current && piece.startsOn === addOneDay(current.endsOn)) {
          current.endsOn = piece.endsOn;
          current.pieces.push(piece);
        } else {
          current = { startsOn: piece.startsOn, endsOn: piece.endsOn, pieces: [piece] };
          aRuns.push(current);
        }
      }

      // ⭐ T-368 S1 (DEF-433) — the 12-month forward window is no longer an unconditional
      // `seedCalendarMonths(M, 12)`. THAT call is the defect: it opened every month M..M+11
      // regardless of class, so a class-B/C piece anywhere in the window — missing, but BEHIND a
      // later closed period further out — was inserted as `open` right alongside it, and 0160's
      // order-guard trigger then raised on the whole multi-row INSERT, aborting the transaction
      // before the B/C failure lines below were ever computed. Only the WHOLE class-A pieces of
      // each run that fall AT OR AFTER M are opened here, grouped into contiguous runs exactly like
      // the elapsed loop just below; a B/C/D piece is never written, only reported.
      let windowInserted = 0;
      for (const r of aRuns) {
        const forward = r.pieces.filter((p) => p.yearMonth >= mLabel);
        if (forward.length === 0) continue;
        const [y, mo] = forward[0]!.yearMonth.split('-').map(Number) as [number, number];
        const { periodsInserted } = await fiscalPeriodsRepo.seedCalendarMonths(tx, org.id, {
          startYear: y,
          startMonth: mo,
          months: forward.length,
        });
        windowInserted += periodsInserted;
      }
      // ⭐ Arithmetic, not the repo's own skip count: "skipped" now covers BOTH a month that already
      // existed and a month this run deliberately never attempted (B/C/D) — the window is always
      // exactly 12 months, so whatever was not freshly opened was skipped, for either reason.
      const windowSkipped = 12 - windowInserted;

      const failures: SchedulerFailure[] = [];
      let backfilled = 0;
      for (const r of aRuns) {
        // Only the ELAPSED prefix (< M) is this job's to backfill and report — the rest of the
        // run, if any, is exactly M..M+11 and the forward window above already covers it (H9's
        // shape). A run entirely >= M (nothing elapsed) needs no separate call at all.
        const elapsed = r.pieces.filter((p) => p.yearMonth < mLabel);
        if (elapsed.length === 0) continue;

        const [y, mo] = elapsed[0]!.yearMonth.split('-').map(Number) as [number, number];
        const { periodsInserted } = await fiscalPeriodsRepo.seedCalendarMonths(tx, org.id, {
          startYear: y,
          startMonth: mo,
          months: elapsed.length,
        });
        backfilled += periodsInserted;
        // ⚠️ Gated on `periodsInserted === elapsed.length`, the same "only ours" guard the old gap
        // branch used — an overlapping run that lost part of this exact race must not re-report a
        // backfill it did not (fully) do.
        if (periodsInserted === elapsed.length) {
          // §3.2's table: a run reaching all the way to `through` (the scan boundary) with
          // nothing bounding it on the right is THE TAIL — T-276's original shape and its
          // original string, unchanged, so `t276-fiscal-period-seed-job.test.ts`'s case 4 stays
          // green. Any other run is bounded by a real period after it: an INTERIOR hole, T-344's
          // new wording.
          const isTail = r.endsOn === through;
          const firstMonth = elapsed[0]!.yearMonth;
          const lastMonth = elapsed[elapsed.length - 1]!.yearMonth;
          // ⚠️ `before` (this org's real latest period end, read at the top of this function),
          // never `subtractOneDay(r.startsOn)` (review finding, LOW): the run's own start is where
          // this job's A-classification happens to resume, which is NOT the same date when the
          // tail hole's leading edge is a B/C/D piece (a closed year immediately followed by open
          // books) — `r.startsOn` would then be one day past a piece where no period ever existed,
          // not one day past where a real period actually ended.
          const reason = isTail
            ? `coverage gap: periods ended ${before}; backfilled ${periodsInserted} ` +
              `elapsed month(s) ${firstMonth}..${lastMonth} as open — created after their own month ended, ` +
              'so no close ever ran on them'
            : `coverage gap: no period covered ${elapsed[0]!.startsOn}..${elapsed[elapsed.length - 1]!.endsOn}; ` +
              `backfilled ${periodsInserted} elapsed month(s) ${firstMonth}..${lastMonth} as open — created ` +
              'after their own month ended, so no close ever ran on them';
          failures.push({ subjectId: org.id, subjectName: org.name, reason });
        }
      }

      // Class B/C/D — never written here (Q1: the job reports, never fills inside closed books,
      // and never fills a part-month piece). Always reported, every run, until an administrator
      // acts (invariant 6, DEF-044's own "no silent no-op" rule).
      for (const piece of pieces) {
        if (piece.class === 'B') {
          failures.push({
            subjectId: org.id,
            subjectName: org.name,
            reason:
              `month ${piece.yearMonth} is missing inside closed books, so posts dated in it are refused; ` +
              `an administrator can create it as ${piece.targetStatus} with "Create the missing month" on /findings`,
          });
        } else if (piece.class === 'C') {
          failures.push({
            subjectId: org.id,
            subjectName: org.name,
            reason:
              `${piece.startsOn}..${piece.endsOn} (part of ${piece.yearMonth}) is missing inside closed books, ` +
              `so posts dated in it are refused; an administrator can create it as ${piece.targetStatus} with ` +
              '"Create the missing month" on /findings',
          });
        } else if (piece.class === 'D') {
          failures.push({
            subjectId: org.id,
            subjectName: org.name,
            reason:
              `coverage hole NOT filled: no period covers ${piece.startsOn}..${piece.endsOn} (part of ` +
              `${piece.yearMonth}); the job creates whole months only, and the action refuses while earlier ` +
              'months are open; posts dated there stay refused',
          });
        }
      }

      const after = await fiscalPeriodsRepo.latestPeriodEnd(tx, org.id);
      const missingClosedCount = pieces.filter((p) => p.class === 'B' || p.class === 'C').length;
      const openHoleCount = pieces.filter((p) => p.class === 'D').length;

      return {
        posted: windowInserted + backfilled,
        skipped: windowSkipped,
        failures,
        detail:
          `window ${mLabel}..${addMonths(mLabel, 11)} · inserted ${windowInserted + backfilled} · ` +
          `skipped ${windowSkipped} · coverage now ends ${after ?? 'never'} · ` +
          `missing in closed books ${missingClosedCount} · part-month holes in open books ${openHoleCount}`,
      };
    });
  });
}

/** `date` plus one day, as `YYYY-MM-DD` — local, like `monthIndex`/`addMonths` above. */
function addOneDay(date: string): string {
  const [y, mo, d] = date.split('-').map(Number) as [number, number, number];
  return new Date(Date.UTC(y, mo - 1, d + 1)).toISOString().slice(0, 10);
}

/** The last day of a `'YYYY-MM'` label, as `YYYY-MM-DD`. */
function monthEndFromLabel(yyyyMm: string): string {
  const [y, mo] = yyyyMm.split('-').map(Number) as [number, number];
  return new Date(Date.UTC(y, mo, 0)).toISOString().slice(0, 10);
}

// =====================================================================================

/**
 * ⭐ **T-401 S6 (Ian, 15 Oct; audit ruling A1) - the usage auto-post sweep, DAILY 14:05 Manila.** Posts every system-made pull usage
 * draft that is past its deadline (`stock/usage-auto-post.ts` holds the rules and the deadline). One org at a time, each under that
 * org's system principal, through `runJobForOrg`: every run writes a `scheduler_runs` row (job `usage_auto_post`), and a draft the
 * system could not post is a failure line, so the run is `partial`, `hadFailures` is true and the script exits non-zero (systemd shows
 * the unit failed). A refused record or a failing org never stops the next.
 */
export interface UsageAutoPostOutcome {
  readonly orgName: string;
  readonly posted: number;
  readonly skipped: readonly { readonly recordId: string; readonly subjectName: string; readonly reason: string }[];
  readonly error?: string;
}

export interface UsageAutoPostSweepResult {
  readonly outcomes: UsageAutoPostOutcome[];
  readonly hadFailures: boolean;
}

export async function usageAutoPostSweep(
  options: { orgId?: string; now: Date; trigger?: 'cron' | 'manual' },
): Promise<UsageAutoPostSweepResult> {
  const { now } = options;
  const trigger = options.trigger ?? 'cron';
  // Bookkeeping only, like the other daily jobs: the Manila month this run happened in.
  const period = toBusinessDate(now).slice(0, 7);
  const orgs = await listOrgsToRun(options.orgId);
  const outcomes: UsageAutoPostOutcome[] = [];
  let failed = false;
  for (const org of orgs) {
    let skipped: { recordId: string; subjectName: string; reason: string }[] = [];
    const run = await runJobForOrg(org, 'usage_auto_post', period, trigger, async () => {
      const result = await asSystem(org.id, (tx) => autoPostDueUsageDrafts(tx, now, trigger === 'manual' ? 'manual' : 'cron'));
      skipped = [...result.skipped];
      return {
        posted: result.posted.length,
        skipped: 0,
        failures: result.skipped.map((s) => ({ subjectId: s.recordId, subjectName: s.subjectName, reason: s.reason })),
        detail: `auto-posted ${result.posted.length} - left as draft ${result.skipped.length}`,
      };
    });
    outcomes.push({ orgName: org.name, posted: run.posted, skipped, ...(run.error ? { error: run.error } : {}) });
    if (run.error || run.failed > 0) failed = true;
  }
  return { outcomes, hadFailures: failed };
}
